WeierstrassCurve.Affine.slope.eq_1.code:
WeierstrassCurve.Affine.slope.eq_1.{u} {F : Type u} [Field F] (W : Affine F) (x₁ x₂ y₁ y₂ : F) :
  W.slope x₁ x₂ y₁ y₂ =
    if x₁ = x₂ then
      if y₁ = W.negY x₂ y₂ then 0 else (3 * x₁ ^ 2 + 2 * W.a₂ * x₁ + W.a₄ - W.a₁ * y₁) / (y₁ - W.negY x₁ y₁)
    else (y₁ - y₂) / (x₁ - x₂)

